shellCommands.command:
cd /home/sandbox/workspace && cat > src/App.css <<'EOF'
/* page-constructor does not ship a box-sizing reset; without it the grid padding overflows the viewport */
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}
EOF
cat > src/App.tsx <<'EOF'
import { PageConstructor, PageConstructorProvider } from '@gravity-ui/page-constructor';
import type { PageContent } from '@gravity-ui/page-constructor';
import '@gravity-ui/page-constructor/styles/styles.css';

import './App.css';

const content: PageContent = {
  blocks: [
    {
      type: 'header-block',
      centered: true,
      width: 'm',
      verticalOffset: 'l',
      overtitle: 'Учёт времени для небольших команд',
      title: 'Знайте, куда уходит время команды',
      description:
        'Таймлог — простой трекер рабочего времени: запуск таймера в один клик, отчёты по проектам и людям, без лишних настроек.',
      buttons: [
        { text: 'Попробовать бесплатно', theme: 'action', url: '#start' },
        { text: 'Как это работает', theme: 'outlined', url: '#features' },
      ],
    },
    {
      type: 'card-layout-block',
      anchor: { text: 'Преимущества', url: 'features' },
      title: 'Почему Таймлог',
      colSizes: { all: 12, sm: 6, md: 4 },
      children: [
        {
          type: 'basic-card',
          border: 'line',
          gravityIcon: { name: 'Clock', color: 'brand' },
          title: 'Таймер в один клик',
          text: 'Запускайте и останавливайте учёт прямо из списка задач. Забыли нажать — добавьте время вручную задним числом.',
        },
        {
          type: 'basic-card',
          border: 'line',
          gravityIcon: { name: 'ChartColumn', color: 'brand' },
          title: 'Понятные отчёты',
          text: 'Сводка по проектам, сотрудникам и неделям собирается автоматически. Экспорт в CSV для счетов и зарплаты.',
        },
        {
          type: 'basic-card',
          border: 'line',
          gravityIcon: { name: 'Persons', color: 'brand' },
          title: 'Вся команда вместе',
          text: 'Пригласите коллег по ссылке, распределите по проектам и смотрите загрузку каждого в реальном времени.',
        },
      ],
    },
    {
      type: 'content-layout-block',
      anchor: { text: 'Начать', url: 'start' },
      centered: true,
      textWidth: 's',
      textContent: {
        title: 'Начните считать время уже сегодня',
        text: 'Бесплатно для команд до пяти человек. Без карты и без ограничений по проектам.',
        buttons: [{ text: 'Создать аккаунт', theme: 'action', url: '#start' }],
      },
    },
  ],
};

export function App() {
  return (
    <PageConstructorProvider>
      <PageConstructor content={content} />
    </PageConstructorProvider>
  );
}
EOF
echo "=== anchor type ===" && rg -n 'anchor' -A 4 node_modules/@gravity-ui/page-constructor/build/esm/models/constructor-items/blocks.d.ts | head -20; rg -n 'export (interface|type) AnchorProps' -A 5 node_modules/@gravity-ui/page-constructor/build/esm/models/constructor-items/common.d.ts
echo "=== provider theme source ===" && rg -n 'useTheme|theme' node_modules/@gravity-ui/page-constructor/build/esm/containers/PageConstructor/Provider.js | head -8
echo "=== BUILD ===" && timeout 300 npm run build 2>&1 | tail -30

echo "=== css imports ===" && grep -n '@import' node_modules/@gravity-ui/page-constructor/styles/styles.css | head && cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  resolve: {
    // @gravity-ui/page-constructor styles use webpack-style "~@gravity-ui/..." imports
    alias: [{ find: /^~(@gravity-ui\/)/, replacement: '$1' }],
  },
});
EOF
echo "=== BUILD ===" && timeout 300 npm run build 2>&1 | tail -20

timeout 200 npm install -D url 2>&1 | grep -v '^npm warn' | tail -3 && grep -E '"(version|main)"' node_modules/url/package.json && cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: [
      // @gravity-ui/page-constructor styles use webpack-style "~@scope/pkg" imports
      { find: /^~(?=@)/, replacement: '' },
      // @gravity-ui/page-constructor imports Node's "url" module; point it at the browser polyfill
      { find: /^url$/, replacement: 'url/' },
    ],
  },
});
EOF
echo "=== BUILD ===" && timeout 300 npm run build 2>&1 | grep -v '^\s*at ' | tail -15
